CREATE TABLE IF NOT EXISTS sp_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sp_companies(id INTEGER PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sp_securities(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES sp_companies(id),code TEXT UNIQUE NOT NULL,exchange TEXT NOT NULL,name TEXT NOT NULL,list_date TEXT,delist_date TEXT,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sp_aliases(id INTEGER PRIMARY KEY,security_id INTEGER NOT NULL REFERENCES sp_securities(id),code TEXT NOT NULL,name TEXT NOT NULL,recorded_at TEXT NOT NULL,UNIQUE(security_id,code,name));
CREATE INDEX IF NOT EXISTS sp_alias_code ON sp_aliases(code,security_id);
CREATE TABLE IF NOT EXISTS sp_artifacts(id INTEGER PRIMARY KEY,sha256 TEXT UNIQUE NOT NULL,kind TEXT NOT NULL,byte_size INTEGER,path TEXT,availability TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sp_runs(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES sp_companies(id),input_hash TEXT NOT NULL,processor_version TEXT NOT NULL,model TEXT,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,input_tokens INTEGER,output_tokens INTEGER,request_artifact INTEGER REFERENCES sp_artifacts(id),response_artifact INTEGER REFERENCES sp_artifacts(id),error TEXT,UNIQUE(company_id,input_hash,processor_version));
CREATE TABLE IF NOT EXISTS sp_revisions(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES sp_companies(id),number INTEGER NOT NULL,recorded_at TEXT NOT NULL,run_id INTEGER NOT NULL REFERENCES sp_runs(id),reason TEXT NOT NULL,security_json TEXT NOT NULL,UNIQUE(company_id,number));
CREATE INDEX IF NOT EXISTS sp_revision_time ON sp_revisions(company_id,recorded_at,number);
CREATE TABLE IF NOT EXISTS sp_documents(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES sp_companies(id),slot TEXT NOT NULL,kind TEXT NOT NULL,title TEXT,period_start TEXT,period_end TEXT,published_at TEXT,collected_at TEXT,effective_at TEXT,source_url TEXT,original_artifact INTEGER REFERENCES sp_artifacts(id),parsed_artifact INTEGER REFERENCES sp_artifacts(id),prior_id INTEGER REFERENCES sp_documents(id),status TEXT NOT NULL,run_id INTEGER NOT NULL REFERENCES sp_runs(id),created_at TEXT NOT NULL,legacy_id TEXT);
CREATE INDEX IF NOT EXISTS sp_docs_period ON sp_documents(company_id,period_end,slot);
CREATE TABLE IF NOT EXISTS sp_revision_documents(revision_id INTEGER NOT NULL REFERENCES sp_revisions(id),document_id INTEGER NOT NULL REFERENCES sp_documents(id),PRIMARY KEY(revision_id,document_id));
CREATE TABLE IF NOT EXISTS sp_tables(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES sp_documents(id),source_ref TEXT NOT NULL,headers_json TEXT NOT NULL,UNIQUE(document_id,source_ref));
CREATE TABLE IF NOT EXISTS sp_evidence(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES sp_documents(id),source_ref TEXT NOT NULL,kind TEXT NOT NULL,line_start INTEGER,line_end INTEGER,pdf_page INTEGER,row_number INTEGER,column_number INTEGER,chapter TEXT,quote TEXT,locator_json TEXT NOT NULL,UNIQUE(document_id,source_ref));
CREATE TABLE IF NOT EXISTS sp_source_records(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES sp_documents(id),source_key TEXT NOT NULL,kind TEXT NOT NULL,name TEXT NOT NULL,data_json TEXT NOT NULL,evidence_id INTEGER NOT NULL REFERENCES sp_evidence(id),status TEXT NOT NULL,UNIQUE(document_id,source_key));
CREATE INDEX IF NOT EXISTS sp_source_records_topic ON sp_source_records(kind,name,document_id);
CREATE TABLE IF NOT EXISTS sp_facts(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES sp_documents(id),local_key TEXT NOT NULL,business_key TEXT,original_name TEXT NOT NULL,standard_name TEXT NOT NULL,description TEXT,products_json TEXT NOT NULL,entity TEXT,stage TEXT NOT NULL,activities_json TEXT NOT NULL,status TEXT NOT NULL,reviewer TEXT,reviewed_at TEXT,prior_id INTEGER REFERENCES sp_facts(id),run_id INTEGER NOT NULL REFERENCES sp_runs(id),created_at TEXT NOT NULL,UNIQUE(document_id,local_key));
CREATE INDEX IF NOT EXISTS sp_fact_doc ON sp_facts(document_id,status,stage);
CREATE TABLE IF NOT EXISTS sp_fact_evidence(fact_id INTEGER NOT NULL REFERENCES sp_facts(id),evidence_id INTEGER NOT NULL REFERENCES sp_evidence(id),field TEXT NOT NULL,PRIMARY KEY(fact_id,evidence_id,field));
CREATE TABLE IF NOT EXISTS sp_contexts(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES sp_documents(id),table_id INTEGER REFERENCES sp_tables(id),source_ref TEXT NOT NULL,label TEXT NOT NULL,dimension TEXT NOT NULL,scope TEXT NOT NULL,entity TEXT,period_start TEXT,period_end TEXT,unit TEXT,currency TEXT,basis_json TEXT NOT NULL,parent_id INTEGER REFERENCES sp_contexts(id),orientation TEXT NOT NULL,status TEXT NOT NULL,non_overlapping INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS sp_context_doc ON sp_contexts(document_id,source_ref);
CREATE TABLE IF NOT EXISTS sp_metrics(code TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sp_observations(id INTEGER PRIMARY KEY,context_id INTEGER NOT NULL REFERENCES sp_contexts(id),metric TEXT NOT NULL REFERENCES sp_metrics(code),value TEXT,raw_value TEXT,precision INTEGER,basis TEXT NOT NULL,evidence_id INTEGER REFERENCES sp_evidence(id),status TEXT NOT NULL,formula_version TEXT,inputs_json TEXT,prior_id INTEGER REFERENCES sp_observations(id),run_id INTEGER NOT NULL REFERENCES sp_runs(id),created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sp_obs_context ON sp_observations(context_id,metric);
CREATE TABLE IF NOT EXISTS sp_links(id INTEGER PRIMARY KEY,fact_id INTEGER NOT NULL REFERENCES sp_facts(id),context_id INTEGER NOT NULL REFERENCES sp_contexts(id),relation TEXT NOT NULL,reason TEXT,status TEXT NOT NULL,prior_id INTEGER REFERENCES sp_links(id),run_id INTEGER NOT NULL REFERENCES sp_runs(id),created_at TEXT NOT NULL,UNIQUE(fact_id,context_id));
CREATE INDEX IF NOT EXISTS sp_link_context ON sp_links(context_id,fact_id);
CREATE TABLE IF NOT EXISTS sp_rules(scheme TEXT NOT NULL,version TEXT NOT NULL,industry TEXT NOT NULL,name TEXT NOT NULL,inclusion TEXT NOT NULL,exclusion TEXT NOT NULL,PRIMARY KEY(scheme,version,industry));
CREATE TABLE IF NOT EXISTS sp_classifications(id INTEGER PRIMARY KEY,fact_id INTEGER NOT NULL REFERENCES sp_facts(id),scheme TEXT NOT NULL,rule_version TEXT NOT NULL,industry TEXT NOT NULL,reason TEXT NOT NULL,relation_kind TEXT NOT NULL,status TEXT NOT NULL,judgement_source TEXT,reviewer TEXT,reviewed_at TEXT,effective_at TEXT,prior_id INTEGER REFERENCES sp_classifications(id),run_id INTEGER NOT NULL REFERENCES sp_runs(id),created_at TEXT NOT NULL,FOREIGN KEY(scheme,rule_version,industry) REFERENCES sp_rules(scheme,version,industry));
CREATE INDEX IF NOT EXISTS sp_class_fact ON sp_classifications(fact_id,industry,status);
CREATE TABLE IF NOT EXISTS sp_revision_classifications(revision_id INTEGER NOT NULL REFERENCES sp_revisions(id),classification_id INTEGER NOT NULL REFERENCES sp_classifications(id),PRIMARY KEY(revision_id,classification_id));
CREATE TABLE IF NOT EXISTS sp_issues(id INTEGER PRIMARY KEY,document_id INTEGER REFERENCES sp_documents(id),run_id INTEGER NOT NULL REFERENCES sp_runs(id),object_ref TEXT,type TEXT NOT NULL,severity TEXT NOT NULL,fields_json TEXT NOT NULL,reason TEXT NOT NULL,refs_json TEXT NOT NULL,status TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sp_issue_doc ON sp_issues(document_id,status);
CREATE TABLE IF NOT EXISTS sp_heads(company_id INTEGER PRIMARY KEY REFERENCES sp_companies(id),revision_id INTEGER NOT NULL REFERENCES sp_revisions(id),number INTEGER NOT NULL,period_end TEXT,status TEXT NOT NULL,purity TEXT NOT NULL,primary_industry TEXT,derived_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sp_sector_index(company_id INTEGER NOT NULL REFERENCES sp_companies(id),industry TEXT NOT NULL,stage TEXT NOT NULL,status TEXT NOT NULL,PRIMARY KEY(company_id,industry,stage,status));
CREATE INDEX IF NOT EXISTS sp_sector_lookup ON sp_sector_index(industry,stage,status,company_id);
